 "content": "from collections import deque


def transform(grid):
    """Fill rectangular color outlines; odd-sized holes are 7, even-sized are 2."""
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                x, y = q.popleft()
                cells.add((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            r0 = min(x for x, _ in cells)
            r1 = max(x for x, _ in cells)
            c0 = min(y for _, y in cells)
            c1 = max(y for _, y in cells)
            perimeter = (
                {(r0, y) for y in range(c0, c1 + 1)}
                | {(r1, y) for y in range(c0, c1 + 1)}
                | {(x, c0) for x in range(r0, r1 + 1)}
                | {(x, c1) for x in range(r0, r1 + 1)}
            )
            if cells != perimeter or r1 - r0 < 2 or c1 - c0 < 2:
                continue
            ih, iw = r1 - r0 - 1, c1 - c0 - 1
            fill = 7 if ih % 2 == 1 and iw % 2 == 1 else 2
            for x in range(r0 + 1, r1):
                for y in range(c0 + 1, c1):
                    if grid[x][y] == bg:
                        out[x][y] = fill
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin)))
